def compute(vars):
    net_adjustment = vars["v1"] + vars["v2"] + vars["v3"]
    adjusted_balance = vars["v4"]

    if adjusted_balance == 0:
        return None

    value = (net_adjustment / adjusted_balance) * 100

    return {
        "value": value,
        "trace": {
            "net_adjustment": net_adjustment,
            "adjusted_balance": adjusted_balance,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }

